import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.DbSlGjul.js";const p=JSON.parse('{"title":"Open calls for contributions","description":"Open calls for HiveBoard learning datasets and functional assets for activities of daily living and bimanual manipulation.","frontmatter":{"description":"Open calls for HiveBoard learning datasets and functional assets for activities of daily living and bimanual manipulation."},"headers":[],"relativePath":"contribute/index.md","filePath":"contribute/index.md","lastUpdated":1788882780000}'),o={name:"contribute/index.md"};function s(r,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="open-calls-for-contributions" tabindex="-1">Open calls for contributions <a class="header-anchor" href="#open-calls-for-contributions" aria-label="Permalink to &quot;Open calls for contributions&quot;">​</a></h1><p>We invite laboratories, individual researchers, and teams to contribute manipulation datasets using HiveBoard or develop assets for two benchmark extensions.</p><table tabindex="0"><thead><tr><th>Open call</th><th>Scope</th></tr></thead><tbody><tr><td><a href="/hivedocs/contribute/evaluations">Learning datasets</a></td><td>Demonstrations and robot rollouts with states, actions, camera observations, calibration, and task outcomes for learning-based methods</td></tr><tr><td><a href="/hivedocs/contribute/adl">Activities of daily living (ADL)</a></td><td>Mechanisms representing everyday manipulation tasks, such as operating closures, dispensing items, or handling household objects</td></tr><tr><td><a href="/hivedocs/contribute/bimanual">Bimanual manipulation</a></td><td>Tasks that require coordinated action by two hands or end-effectors</td></tr></tbody></table><h2 id="contribute-a-learning-dataset" tabindex="-1">Contribute a learning dataset <a class="header-anchor" href="#contribute-a-learning-dataset" aria-label="Permalink to &quot;Contribute a learning dataset&quot;">​</a></h2><p>Record robot states, executed commands, and camera streams while performing HiveBoard tasks. Include timestamps, calibration, an episode index, and a loading example. There is no fixed episode count or requirement to cover all conditions; larger collections are encouraged. Contact the organizers before collection to agree on tasks, signals, and formats. See the <a href="/hivedocs/contribute/evaluations">dataset call</a> for requirements and direct email submission.</p><p>Substantial accepted datasets may establish eligibility for authorship on future dataset papers that use the contribution. Smaller contributions may be acknowledged. See the <a href="/hivedocs/contribute/evaluations#authorship-and-acknowledgments">dataset credit policy</a>.</p><h2 id="propose-a-new-asset" tabindex="-1">Propose a new asset <a class="header-anchor" href="#propose-a-new-asset" aria-label="Permalink to &quot;Propose a new asset&quot;">​</a></h2><p>Contact <a href="mailto:ricardo.godoy@usp.br" target="_blank" rel="noreferrer">Ricardo V. Godoy</a> before starting detailed design or fabrication. Send a short task description, a sketch or reference image, and the intended call. The authors will discuss whether the idea fits the benchmark, overlaps with an existing asset, and can be tested consistently across platforms.</p><p>An initial discussion establishes the scope; acceptance follows review of the working asset and its files.</p><h2 id="what-to-contribute" tabindex="-1">What to contribute <a class="header-anchor" href="#what-to-contribute" aria-label="Permalink to &quot;What to contribute&quot;">​</a></h2><p>Submit a functional physical prototype, editable CAD, printable files, an articulated simulation model, assembly instructions, task and reset definitions, and validation evidence. The <a href="/hivedocs/contribute/requirements#required-files-and-evidence">submission checklist</a> specifies the complete package.</p><p>Contributing at least one accepted, functional asset with the complete package can establish eligibility for authorship on future papers that use the contribution. Smaller contributions may be acknowledged. Read the <a href="/hivedocs/contribute/requirements#authorship-and-acknowledgments">credit policy</a> before starting.</p><p>The ADL and bimanual calls concern new benchmark extensions. The learning-dataset call has no fixed episode count. Formal benchmark evaluations still require <strong>13 conditions with five trials each, for 65 trials total</strong>. Proposed assets do not enter the current evaluation until a revised protocol is released.</p>',13)])])}const b=t(o,[["render",s]]);export{p as __pageData,b as default};
